tdr = lambda T: [f"{T['best_estimate_hits']}/10", f"{T['top3_hits']}/10", f"{T['null_mean']:.1f} ({int(T['null_p95'])})", pfmt(T['p_perm']), f"{T['slow_hits']}/{T['slow_n']}", f"{T['fast_hits']}/{T['fast_n']}"]
diag_rows = [['Round 1'] + tdr(T1), ['Round 2'] + tdr(T2)]
